import json
import random
import six
from abc import ABCMeta, abstractmethod


class ConnectionOpen(object):

    def __str__(self):
        return "Connection opened."


class ConnectionClose(object):

    def __init__(self, error=""):
        self.error = error

    def __str__(self):
        return "Connection closed. {}".format(self.error)


@six.add_metaclass(ABCMeta)
class AdminApiMessage(dict):

    def __init__(self, *args, **kwargs):
        super(AdminApiMessage, self).__init__(*args, **kwargs)

    def __getattr__(self, attr):
        return self.get(attr)

    def __setattr__(self, attr, value):
        self[attr] = value

    def __str__(self):
        return json.dumps(self._short(self.form()))

    def _short(self, value):
        if isinstance(value, dict):
            return {k: self._short(v) for k, v in value.items()}
        if hasattr(value, "__len__") and len(value) > 100:
            return "{} ... {} of length: {}".format(value[:10], type(value), len(value))
        if isinstance(value, list):
            return [self._short(item) for item in value]

        return value

    def serialize(self):
        """Serialize to JSON string."""
        return json.dumps(self.form(), separators=(',', ':'))

    @abstractmethod
    def form(self):
        """Form message dict."""

    @abstractmethod
    def get_payload(self):
        """Get payload."""


class AdminApiRequest(AdminApiMessage):

    def __init__(self, req_type, name, parameters):
        req_id = random.randint(0, 100000)
        if req_type:
            super(AdminApiRequest, self).__init__(
                {"requestId": req_id, "requestType": req_type,
                 "parameters": {"name": name, "parameters": parameters}})
        elif req_type is None:
            super(AdminApiRequest, self).__init__(
                {"requestId": req_id, "parameters":
                 {"name": name, "parameters": parameters}})


class AdminApiResponse(AdminApiMessage):

    def __init__(self, payload):
        super(AdminApiResponse, self).__init__(payload)

    def match(self, other):
        """Check if response matches other message."""
        return self.requestId == other.requestId

    def is_failure(self):
        """Check if response status is failure."""
        return self.requestStatus == "failed"

    def is_success(self):
        """Check if response status is success."""
        return self.requestStatus == "completed"

    def is_completed(self):
        """Check if request is completed"""
        return self.is_success() or self.is_failure()


class AdminApiMessage_v1(AdminApiMessage):

    def form(self):
        """Form message dict."""
        return self

    def get_payload(self):
        """Get payload."""
        return self.payload


class AdminApiMessage_v2(AdminApiMessage):

    msg_type = "ADMIN_API"

    def form(self):
        """Form message dict."""
        return {"type": self.msg_type, "payload": self}

    def get_payload(self, detailed=False):
        """Get payload."""
        if detailed and isinstance(self, AdminApiResponse_v2):
            payload = dict(self)
        else:
            payload = self.outputFileContent or self.requestMessage

        if isinstance(payload, dict) and "subscriptionData" in payload:
            payload = payload["subscriptionData"]
        return payload


class AdminFileTransferMessage(AdminApiMessage_v2):

    msg_type = "FILE_TRANSFER"

    def match(self, request):
        """Check if message matches request."""
        return self.id == request.requestId


class AdminFileTransferPlanScfMessage(AdminApiMessage_v2):

    msg_type = "FILE_TRANSFER_PLAN_SCF"

    def match(self, request):
        """Check if message matches request."""
        return self.id == request.requestId


class AdminFileTransferRatScfMessage(AdminApiMessage_v2):

    msg_type = "FILE_TRANSFER_RAT_SCF"

    def match(self, request):
        """Check if message matches request."""
        return self.id == request.requestId


class AdminApiRequest_v1(AdminApiRequest, AdminApiMessage_v1):
    pass


class AdminApiRequest_v2(AdminApiRequest, AdminApiMessage_v2):
    pass


class AdminApiResponse_v1(AdminApiResponse, AdminApiMessage_v1):
    pass


class AdminApiResponse_v2(AdminApiResponse, AdminApiMessage_v2):
    pass


def create_response(raw_msg):
    """Parse received data and create proper response depending on type."""
    msg = json.loads(raw_msg)
    msg_type = msg.get("type")
    msg_payload = msg.get("payload", {})

    if msg_type == AdminApiMessage_v2.msg_type:
        return AdminApiResponse_v2(msg_payload)
    elif msg_type == AdminFileTransferMessage.msg_type:
        return AdminFileTransferMessage(msg_payload)
    elif msg_type == AdminFileTransferPlanScfMessage.msg_type:
        return AdminFileTransferPlanScfMessage(msg_payload)
    elif msg_type == AdminFileTransferRatScfMessage.msg_type:
        return AdminFileTransferRatScfMessage(msg_payload)
    else:
        return AdminApiResponse_v1(msg)
